public class ExercicioSecao7B {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Declare três números e calcule a média.");
		int primeiroNumero = 2;
		int segundoNumero= 3;
		int terceiroNumero= 5;
		System.out.println("O 1º número é:" + (primeiroNumero));
		System.out.println("O 2º número é:" + (segundoNumero));
		System.out.println("O 2º número é:" +(terceiroNumero));
		System.out.println("A média é:"+ (primeiroNumero+segundoNumero+terceiroNumero/3));
	}

}
